#!/usr/bin/env python3
"""Check the single InternetMap instance generated by B08."""

from pathlib import Path
import sys

REPO_ROOT = Path(__file__).resolve().parents[3]
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from seedemu.testing import ComposeRuntimeTest


def main() -> int:
    test = ComposeRuntimeTest(__file__)
    services = test.compose.get("services", {})
    api = "emulator_api_server.map.seed.emu"
    topology = "internetmap_toplogy.map.seed.emu"
    geographic = "internetmap_geo.map.seed.emu"
    observer = "traffic_observer.map.seed.emu"
    bridge = "internetMap_network"

    expected_networks = {
        api: {
            bridge: {"ipv4_address": "172.30.0.10"},
            "net_151_net0": {"ipv4_address": "10.151.0.16"},
        },
        topology: {bridge: {"ipv4_address": "172.30.0.11"}},
        geographic: {bridge: {"ipv4_address": "172.30.0.12"}},
    }
    # Bundle services have no Base-node labels, so use their explicit keys.
    for name, networks in expected_networks.items():
        config = services.get(name, {})
        test.structural_check(
            f"{name} has the intended static attachments",
            config.get("networks") == networks and config.get("container_name") == name,
            str(config.get("networks")),
        )
    ipam = test.compose.get("networks", {}).get(bridge, {}).get("ipam", {})
    test.structural_check(
        "default bridge retains IPAM for static addresses",
        {"subnet": "172.30.0.0/24", "gateway": "172.30.0.1"} in ipam.get("config", []),
        str(ipam),
    )

    for name, port in ((topology, 8092), (geographic, 8093)):
        config = services.get(name, {})
        test.structural_check(
            f"{name} publishes its UI and depends on the API",
            f"{port}:80" in config.get("ports", []) and api in config.get("depends_on", []),
            str({key: config.get(key) for key in ("ports", "depends_on")}),
        )
        if name in services:
            test.exec_check(
                f"{name} has a valid Nginx config targeting the API bridge IP",
                name,
                "nginx -t && grep -Fq 'server 172.30.0.10:7071;' /etc/nginx/conf.d/default.conf",
                retries=8, interval=2, timeout=15,
            )
            test.exec_check(
                f"{name} reaches the API bridge interface", name,
                "ping -c 2 -W 2 172.30.0.10 >/dev/null",
                retries=8, interval=2, timeout=15,
            )

    config = services.get(observer, {})
    test.structural_check(
        "observer uses host networking and control port 8091",
        config.get("container_name") == observer
        and config.get("network_mode") == "host"
        and not config.get("networks")
        and config.get("environment", {}).get("TRAFFIC_CONTROL_ADDR") == ":8091",
        str({key: config.get(key) for key in ("network_mode", "networks", "environment")}),
    )
    test.structural_check(
        "geographic UI can proxy to the host observer",
        services.get(geographic, {}).get("extra_hosts", {}).get("host.docker.internal") == "host-gateway",
        str(services.get(geographic, {}).get("extra_hosts")),
    )
    if geographic in services:
        test.exec_check(
            "geographic Nginx config targets observer control port",
            geographic,
            "grep -Fq 'server host.docker.internal:8091;' /etc/nginx/conf.d/default.conf",
            retries=8, interval=2, timeout=15,
        )
    if api in services:
        test.exec_check(
            "API has its internal address and gateway",
            api,
            "ip -o -4 addr show | grep -Fq '10.151.0.16/' "
            "&& ip -4 route show default | grep -Fq 'via 10.151.0.254 ' "
            "&& ping -c 2 -W 2 10.151.0.254 >/dev/null",
            retries=8, interval=2, timeout=15,
        )
    for name in (api, topology, geographic, observer):
        if name in services:
            test.exec_check(
                f"{name} resolves the API's shared bridge alias", name,
                "getent ahostsv4 emulator_api_server-e.map.seed.emu "
                "| awk '$1 == \"172.30.0.10\" {found=1} END {exit !found}'",
                retries=8, interval=2, timeout=15,
            )

    # UI HTTP probes and service readiness run in example.yaml. Observer running
    # state and configuration do not establish packet-capture/control correctness.
    test.write_summary("b08-runtime-test.json")
    return test.exit_code()


if __name__ == "__main__":
    raise SystemExit(main())
